function glue_family(dbs, grid):
  out := empty database
  for each cell p in grid:
    out[p] := blank
    for each db in dbs:
      if db[p] is filled:
        out[p] := db[p]; break   # first defined value wins
  return out

function sheaf_impute(dbs, grid):
  for each unordered pair (a, b) in dbs:
    for each cell p in grid:
      if a[p] filled and b[p] filled and a[p] != b[p]:
        return NONE          # no consistent imputation exists
  return glue_family(dbs, grid)   # canonical least common extension
